const items = $input.all();
const enrichedItems = [];

for (const item of items) {
  const incident = $('Extract Project ID').first().json;

  let sonarMetrics = {};
  let qualityGateStatus = 'UNKNOWN';
  let issues = [];

  try {
    const sonarData = $('Fetch SonarQube Data').first().json;
    const measures = sonarData.component?.measures || [];
    measures.forEach(m => { sonarMetrics[m.metric] = m.value; });
    qualityGateStatus = sonarMetrics['alert_status'] || 'UNKNOWN';
  } catch(e) {}

  try {
    const issuesData = $('Fetch SonarQube Issues').first().json;
    issues = (issuesData.issues || []).map(i => ({
      key: i.key,
      rule: i.rule,
      severity: i.severity,
      message: i.message,
      component: i.component.split(':').pop(),
      line: i.line,
      type: i.type,
      effort: i.effort,
      debt: i.debt,
      tags: i.tags,
      url: `http://172.31.172.61:9000/project/issues?id=pfe-devsecops-2026&open=${i.key}`
    }));
  } catch(e) {}

  const enriched = {
    ...incident,
    enrichedContext: {
      source: 'SonarQube',
      projectKey: 'pfe-devsecops-2026',
      qualityGate: { status: qualityGateStatus },
      issues: {
        total: issues.length,
        bugs: parseInt(sonarMetrics['bugs'] || 0),
        vulnerabilities: parseInt(sonarMetrics['vulnerabilities'] || 0),
        codeSmells: parseInt(sonarMetrics['code_smells'] || 0),
        securityHotspots: parseInt(sonarMetrics['security_hotspots'] || 0),
        details: issues
      },
      metrics: {
        coverage: sonarMetrics['coverage'] || null,
        duplications: sonarMetrics['duplicated_lines_density'] || null,
        reliabilityRating: sonarMetrics['reliability_rating'] || null,
        securityRating: sonarMetrics['security_rating'] || null,
        maintainabilityRating: sonarMetrics['sqale_rating'] || null
      },
      dashboardUrl: 'http://172.31.172.61:9000/dashboard?id=pfe-devsecops-2026'
    },
    enrichedAt: new Date().toISOString()
  };

  enrichedItems.push({ json: enriched });
}
return enrichedItems;

