  const firstBrace = cleaned.indexOf('{');
  const lastBrace = cleaned.lastIndexOf('}');
  if (firstBrace !== -1 && lastBrace !== -1) {
    cleaned = cleaned.substring(firstBrace, lastBrace + 1);
  }

  // Remplacer les backticks imbriqués dans les valeurs string
  cleaned = cleaned.replace(/```json\n?/g, '').replace(/```\n?/g, '');

  parsed = JSON.parse(cleaned);
} catch(e) {
  // Extraction manuelle des champs clés
  const extract = (key) => {
    const match = content.match(new RegExp('"' + key + '"\\s*:\\s*"([^"]*)"'));
    return match ? match[1] : null;
  };
  const extractNum = (key) => {
    const match = content.match(new RegExp('"' + key + '"\\s*:\\s*(\\d+)'));
    return match ? parseInt(match[1]) : 0;
  };
  parsed = {
    decision:        extract('decision')       || 'NOTIFY_ONLY',
    confidenceScore: extractNum('confidenceScore') || 0,
    securityLevel:   extract('securityLevel')  || 'LOW',
    decisionReason:  'Parse error: ' + e.message,
    errorsSummary:   extract('errorsSummary')  || '',
    cicdIssues:      [],
    securityIssues:  {},
    agentActions:    {},
    developerActions:[],
    recommendations: []
  };
}

if (parsed.reasoning && !parsed.decisionReason) {
  parsed.decisionReason = parsed.reasoning;
}

return [{ json: parsed }];

